 "content": "def transform(grid):
    """Copy the colored motif around its 5 anchor to each isolated 5 target."""
    h, w = len(grid), len(grid[0])
    fives = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]

    def nearby_colors(anchor):
        ar, ac = anchor
        return [(r - ar, c - ac, grid[r][c])
                for r in range(max(0, ar - 3), min(h, ar + 4))
                for c in range(max(0, ac - 3), min(w, ac + 4))
                if grid[r][c] != 0 and (r, c) != anchor]

    # The motif anchor is the 5 surrounded by the motif's other colored cells.
    source = max(fives, key=lambda p: len(nearby_colors(p)))
    offsets = nearby_colors(source)
    out = [row[:] for row in grid]
    for target in fives:
        if target == source:
            continue
        tr, tc = target
        out[tr][tc] = 0
        for dr, dc, color in offsets:
            r, c = tr + dr, tc + dc
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = color
    return out
